          <label for="notes">A brief note (goals, pets, pregnancy)</label>
          <textarea id="notes" rows="4" placeholder="Tell us any key considerations"></textarea>

          <div style="display:flex;gap:8px;align-items:center">
            <button class="btn" type="submit">Request booking</button>
            <div class="small">We will follow up to confirm availability.</div>
          </div>
        </form>
      </section>

      <section class="reveal" style="margin-top:14px">
        <h2>Session Planner</h2>
        <div class="planner card" id="planner">
          <label for="intention">What would you like to address?</label>
          <input id="intention" type="text" placeholder="e.g., sharper mornings, calmer nights" />

          <label>Pick scent families</label>
          <div class="tags" id="tagList">
            <button type="button" data-val="Citrus">Citrus</button>
            <button type="button" data-val="Floral">Floral</button>
            <button type="button" data-val="Woody">Woody</button>
            <button type="button" data-val="Herbal">Herbal</button>
            <button type="button" data-val="Balsamic">Balsamic</button>
