    </main>

    <footer style="margin-top:18px" class="muted">Questions? Contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <strong>{{PHONE}}</strong>. Serving {{CITY}}, {{STATE}}.</footer>
  </div>

  <script>
    // Reveal system
    (function(){
      const items = document.querySelectorAll('.reveal');
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(prefersReduced){ items.forEach(i=>i.classList.add('visible')); return; }
      const observer = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('visible'); }); },{threshold:0.12});
      items.forEach(i=>observer.observe(i));
    })();

    // Booking form UX (client-only)
    document.getElementById('bookingForm').addEventListener('submit',function(e){
      e.preventDefault();
      const name = document.getElementById('name').value;
      const email = document.getElementById('email').value;
      const service = document.getElementById('service').value;
      const notes = document.getElementById('notes').value;
      alert('Thanks, ' + (name||'friend') + '. We received your request for: ' + service + '. We will follow up at ' + email + '.');
      this.reset();
    });

    // Planner logic (duplicated interactive widget feature)
    (function(){
      const tagButtons = document.querySelectorAll('#tagList button');
      const make = document.getElementById('makePlan');
      const clear = document.getElementById('clearPlan');
      const copyBtn = document.getElementById('downloadPlan');
      const output = document.getElementById('planOutput');
      const intention = document.getElementById('intention');
      const sens = document.getElementById('sensPlan');
      const pets = document.getElementById('petsPlan');
      const preg = document.getElementById('pregPlan');

      tagButtons.forEach(b=>b.addEventListener('click',()=>b.classList.toggle('active')));

      function build(){
        const families = Array.from(tagButtons).filter(t=>t.classList.contains('active')).map(t=>t.dataset.val).join(', ') || 'None';
        const lines = [];
        lines.push('Prepared plan — share this when booking:');
        lines.push('Intention: ' + (intention.value || '—'));
        lines.push('Scent families: ' + families);
        lines.push('Sensitivity: ' + sens.value);
        lines.push('Pets in home: ' + (pets.checked ? 'Yes' : 'No'));
        lines.push('Pregnancy: ' + (preg.checked ? 'Yes' : 'No'));
        lines.push('Recommendation: Patch test recommended. Follow dilution instructions provided during session. Avoid oils known to be risky for cats.');
        return lines.join('\n');
      }

      make.addEventListener('click',()=>{ output.textContent = build(); });
      clear.addEventListener('click',()=>{ intention.value=''; tagButtons.forEach(b=>b.classList.remove('active')); sens.selectedIndex=0; pets.checked=false; preg.checked=false; output.textContent='No plan yet. Use the fields above.'; });
      copyBtn.addEventListener('click',async ()=>{
        try{ await navigator.clipboard.writeText(output.textContent); copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy plan',1500); }catch(e){ alert('Copy not available — select and copy manually.'); }
      });
    })();
  </script>
</body>
</html>"} 
